\documentclass{article}
\usepackage[utf8]{inputenc}
\usepackage{amsmath}
\usepackage{calc}
\usepackage{enumitem}
\usepackage{soul}

\newcommand{\ex}[1]{\boxed{\text#1}}
\newcommand{\expr}[1]{\textrm#1}

\newenvironment{steps}
  {\begin{enumerate}[leftmargin = *, noitemsep, topsep = 1.5ex, itemsep=0ex]
  }
  {\end{enumerate}}

\begin{document}

\begin{steps}
\item We have the product of our numbers, with $z$ : $xy$, and the product of our friend's numbers, with $w$ : $(x-4)(2y-1)$.

\item To make $w$ be one greater than $z$, we need to satisfy the following equation:
  \begin{align*}
    (x-4)(2y-1) &= (xy) + 1 \\
    xy - 4y + x - 4 &= xy + 1
  \end{align*}
  We can bring $xy$ to one side:
  \begin{equation*}
    3y - 4 = x
  \end{equation*}

\item Rearrange the equation to solve for $x$, and then substitute it in our product $xy$. We get
  \begin{equation*}
    xy = 4y - 3y^2
  \end{equation*}

\item Now, according to our problem, the numbers we picked are between $1$ and $10$, but since $x$ is directly mapped to $y$ through the above equation, we are less restrictive. We only need to ensure that $y \in \expr{\left[4,\frac{9}{2}\right]}$.

\item Therefore, taking for example $y = 5$, we get $x = 3y - 4 = 19$. Thus the product of our numbers:
  \begin{equation*}
    xy = 19 \times 5 = \ex{{95}}
  \end{equation*}
\end{steps}

\end{document}

